                            className="p-1 hover:bg-secondary rounded-lg text-accent"
                            title="Generate Individual Packing List Snapshot"
                          > | handleGenerateInvoice(r.id)}
                              className="p-1 hover:bg-secondary rounded-lg text-accent"
                              title="Generate Invoice"
                            > | handleGenerateInvoice(r.id)}
                          className="min-h-[36px] px-3 py-1.5 rounded-lg border border-accent text-accent text-xs font-medium"
                        >
                          Generate Invoice | handleGenerateReceipt(r.id)}
                              className="p-1 hover:bg-success-soft rounded-lg text-success"
                              title="Generate Receipt"
